	}
}

// The cap holds across merges and the total does not depend on their order.
func TestToolEntriesCapHoldsAcrossMerges(t *testing.T) {
	if testing.Short() {
		t.Skip("builds more than maxToolEntries lines")
	}
	n := maxToolEntries + 25
	all := distinctToolLines(n)
	half := n / 2
	build := func(first, second []tline) *table {
		tb := feed(first)
		tb.merge(feed(second))
		return tb
	}
	for name, tb := range map[string]*table{
		"merge(A,B)": build(all[:half], all[half:]),
		"merge(B,A)": build(all[half:], all[:half]),
	} {
		if len(tb.tools) > maxToolEntries {
			t.Errorf("%s: len(tools) = %d, want at most %d", name, len(tb.tools), maxToolEntries)
		}
		if got := mainOf(t, tb).ToolCalls; got != n {
			t.Errorf("%s: ToolCalls = %d, want %d", name, got, n)
		}
	}
}

// A huge tool id or message id is stored in bounded form, and two ids that
// share their first maxLabelLen bytes stay distinct.
func TestLongToolIDsAreBoundedWithoutCollision(t *testing.T) {
	prefix := strings.Repeat("x", maxLabelLen+500)
	tb := feed([]tline{
		pl(0, toolLine(prefix+"M1", 0, prefix+"a", "")),
		pl(1000, toolLine(prefix+"M1", 0, prefix+"b", "")),
		pl(2000, toolLine(prefix+"M1", 0, prefix+"a", "")), // repeat
	})
	if got := mainOf(t, tb).ToolCalls; got != 2 {
		t.Errorf("ToolCalls = %d, want 2", got)
	}
	for k := range tb.tools {
		if len(k.id) > maxLabelLen || len(k.msg) > maxLabelLen {
			t.Errorf("stored key too long: id %d bytes, msg %d bytes", len(k.id), len(k.msg))
		}
	}
}
// the aggregate itself must keep the memory bound: after N deltas of lines
// without id the table holds at most maxNoIDEntries entries, and the totals
// are still exact (a spilled line counts, it just has no entry). Which lines
// are the ones spilled follows position (mergeCapped keeps the smallest
// positions), not arrival: the declared exception to D3.
func TestAggregateBoundsNoIDEntriesAcrossDeltas(t *testing.T) {
	s := newSess(t)
	const perDelta, deltas = 35000, 3 // 105000 > maxNoIDEntries
	total := perDelta * deltas
	if total <= maxNoIDEntries {
		t.Fatal("setup: not enough lines to pass the cap")
	}
	batch := bytes.Repeat(append(msgLine("", "m", "end_turn", 1, 0, 0, 0), '\n'), perDelta)
	s.put(s.parent(), nil)
	a := NewAggregate(s.parent())
	for i := 0; i < deltas; i++ {
		s.add(s.parent(), batch)
		readApply(t, a)
	}
	u := a.Usage()
	if len(u.Agents) == 0 || u.Agents[0].Messages != total || u.Agents[0].Tokens.Input != int64(total) || u.Diagnostics.NoMessageID != total {
		t.Fatalf("totals: agents %+v, NoMessageID %d, want %d lines counted once each", u.Agents, u.Diagnostics.NoMessageID, total)
	}
	if n := aggEntries(a); n > maxNoIDEntries {
		t.Errorf("entries = %d, want <= %d", n, maxNoIDEntries)
	}
	assertMatchesParse(t, a, s) // same totals as one sequential read
}

